maxpool_kernel_source = """
__global__ void maxpool_kernel(const float* input, int batch, int num_features, int seq_len,
                               int kernel_size, int stride, int padding, int dilation,
                               float* output) {
    // Each thread processes one element of the reduced sequence (out_seq_len total).
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < seq_len) {
        float max_val = -1e9f;

        // Compute start of the window for this output position:
        int start = idx * stride;
        for (int k = 0; k < kernel_size; ++k) {
            int input_idx = start + k * dilation;
            if (input_idx < seq_len) {
                max_val = input[input_idx];
            }
        }

        output[idx] = max_val;
    }
}

torch::Tensor maxpool_cuda(torch::Tensor x, int kernel_size, int stride, int padding, int dilation, bool return_indices) {
    auto batch_size = x.size(0);
    auto num_features = x.size(1);
    auto seq_len = x.size(2);

    // Compute output sequence length
    int out_seq_len = (seq_len + 2 * padding - kernel_size) / (stride * dilation) + 1;
    if (out_seq_len < 0) {
        out_seq_len = 0;
    }

    auto out_shape = torch.Size(batch_size, num_features, out_seq_len);
    auto out = torch::empty(out_shape, x.dtype());

    const int BLOCK_SIZE = 256;
    const int NUM_BLOCKS = (out_seq_len + BLOCK_SIZE - 1) / BLOCK_SIZE;

    maxpool_kernel<<<NUM_BLOCKS, BLOCK_SIZE>>>(
        x.data_ptr<float>(),
        batch_size,
        num_features,
        seq_len,
        kernel_size,
        stride,
        padding,
        dilation,
        out.data_ptr<float>(),
        false
    );

    return out;
}
"""

